package net.glaced.desertjunglecore.command;
import java.util.*;import net.glaced.desertjunglecore.event.EventService;import org.bukkit.command.*;
public final class EventCommand implements CommandExecutor,TabCompleter{private final EventService event;public EventCommand(EventService e){event=e;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!s.hasPermission("desertjungle.event.admin")){s.sendMessage("No permission.");return true;}if(a.length!=1){s.sendMessage("/event <start|stop|pause|resume>");return true;}switch(a[0].toLowerCase()){case "start"->event.start();case "stop"->event.stop();case "pause"->event.pause();case "resume"->event.resume();default->{s.sendMessage("/event <start|stop|pause|resume>");return true;}}return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[]a){return a.length==1?List.of("start","stop","pause","resume"):List.of();}}
